from __future__ import annotations
import logging
from datetime import datetime
from typing import Union, List

from ncclient.transport.notify import Notification
from taf.ul.oran_mplane.core.connection_factory import ConnectionFactory

from taf.ul.oran_mplane.core.communication import Communication
from taf.ul.oran_mplane.core.procedures import Procedures
from taf.ul.oran_mplane.tools.rpc_talker import RpcTalker


class OranMplane:
    """
    DU_IP = "172.17.0.1"
    RU_IP = "172.17.0.10"
    Router for connect SSH example:
    router = {"session1": {"host": RU_IP, "port": 830, "username": "root",
                           "password": "root", "hostkey_verify" : False, "look_for_keys" : False,
                           "device_params" : {"name": "rfsw"}, "protocol": "ssh"}}
    Router for call home SSH example:
    router = {"session1": {"host": DU_IP, "port": 4334, "username": "root",
                           "password": "root", "hostkey_verify" : False, "look_for_keys" : False,
                           "device_params" : {"name": "sros"}, "protocol": "ssh"}}
    Router for call home TLS example:
    CERT_FILE = "/opt/dev/tls_certs/odusim.crt"
    KEY_FILE = "/opt/dev/tls_certs/odusim.key"
    CA_CERTS = "/opt/dev/tls_certs/ca.pem"
    router = {"session1": {"host": DU_IP, "port": 4335, "keyfile": KEY_FILE,
                           "certfile": CERT_FILE, "ca_certs": CA_CERTS, "timeout": 60, "protocol": "tls"}}
    """

    def __init__(
        self,
        router: dict,
        logger=None,
        virtual_connection: bool = False,
    ):
        """Creation of NETCONF connection object. Supported protocols:
        SSH: https://datatracker.ietf.org/doc/html/rfc4742
        TLS: https://datatracker.ietf.org/doc/html/rfc7589
        :param router: name of session, string value example: "session1"
        :param logger: external logger name, default None. For None new logger will be created.
        :param virtual_connection: indicates whether virtual connection should be used.
        :return: object of NETCONF session
        """
        self.router = router
        self.logger = logger
        self.connection = ConnectionFactory.create(virtual_connection=virtual_connection)(
            router=router, logger=logger
        )
        self._communication: Communication | None = None
        self._procedures: Procedures | None = None

    @property
    def communication(self) -> Communication:
        """Initialize and return Communication object."""
        if self._communication is None:
            self._communication = Communication(manager=self, logger=self.logger)
        return self._communication

    @property
    def procedures(self) -> Procedures:
        """Initialize and return Procedures object."""
        if self._procedures is None:
            self._procedures = Procedures(communication=self.communication, logger=self.logger)
        return self._procedures

    def connect(self, session: str):
        """Method to achieve NETCONF connection via connect method. DU request connection
        :param session: string value example: "session1"
        :return: object of NETCONF session
        """
        self.connection.connect(session)

    def call_home(self, session: str):
        """Method to achieve NETCONF connection via call_home method. DU listen connection
        :param session: string value example: "session1"
        :return: object of NETCONF session
        """
        self.connection.call_home(session)

    def close_all_sessions(self, closing_socket_only: bool = False):
        """Method to close all ssh sessions created by "connect_ssh" or "call_home_ssh" method
        :return: None
        """
        self.procedures.stop_all_monitoring_threads()
        self.connection.close_all_sessions(closing_socket_only=closing_socket_only)

    def close_session(self, session: str, *, closing_socket_only: bool = False) -> None:
        """Close specific NETCONF session with its all dependencies.

        :param session: NETCONF session name to terminate.
        :param closing_socket_only: Flag determines whether socket is to be closed only.
        """
        self.procedures.stop_monitoring_thread(session)
        self.connection.close_session(session, closing_socket_only=closing_socket_only)

    # pylint: disable=too-many-arguments
    def get(
        self,
        session: str,
        msg_format: str,
        msg: dict,
        validation_mode: str = "deepdiff",
        exclude_paths: Union[None, List[str]] = None,
        with_defaults=None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> str:
        """Method to execute NETCONF operation "get"
        Execution of "connect" method is a precondition.
        :param session: string value example: "session1"
        :param msg_format: enum: ["xml", "xpath, "dictionary"]
        :param msg: it is dict with request and expected response.
            Example of msg in format xml:
                                    {"request": "<software-inventory "
                                               "xmlns='urn:o-ran:software-management:1.0'>"
                                               "</software-inventory>",
                                    "expected_response": "<software-slot>"}
            Example of msg in format xpath:
                                   {"request": {
                                       "namespace": "urn:o-ran:software-management:1.0",
                                       "expression": "software-inventory"},
                                       "expected_response": "<software-slot>"}
        :param validation_mode: enum ["string", "deepdiff", "skip_validation"].
            If deepdiff is set we can also use regex to values validation.
            It is required to start regex as '(' and end as ')'
            Example: {"expected_response" : {date': "(\\d\\d\\d\\d-\\d\\d-\\d\\d)"}}
            In order to treat value as regex it is required to start string with '('
            and end with ')' parentheses are not used for grouping.
        :param exclude_paths: optional, used when validation_mode is deepdiff
        :param with_defaults: enum [None, "report-all", "trim", "explicit", "report-all-tagged"].
        :param ignore_dictionary_item_added: ignores additional paths in response.
        :param ignore_iterable_item_added: ignores additional paths in response.
        :param kwargs:
                force_list - parameter that will contain tuple or key/value for given child which will be enforced to
                    be kept in list format.
                    Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                     when it is a single element
                log_ignored_items - additional parameter to log ignored items in deepdiff. By default, True.
                log_type_mismatch - additional parameter to log mismatched items in deepdiff.
                 By default, False.
                exclude_regex_paths: List of path regexes to exclude in deepdiff.
        :return: response as str
        """
        _timestamp, rsp = self.communication.get(
            session=session,
            msg_format=msg_format,
            msg=msg,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            with_defaults=with_defaults,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )
        return rsp

    def get_with_timestamp(
        self,
        session: str,
        msg_format: str,
        msg: dict,
        validation_mode: str = "string",
        exclude_paths: Union[None, List[str]] = None,
        with_defaults=None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> tuple[datetime, str]:
        """Perform a NETCONF "get" operation and return the response along with its timestamp.

        All parameters are the same as in the get method.
        Please note that the timestamp is more precise for SSH connections than for TLS due to implementation details.
        """
        return self.communication.get(
            session=session,
            msg_format=msg_format,
            msg=msg,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            with_defaults=with_defaults,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )

    def get_without_filter(self, session: str, with_defaults=None):
        """Method to execute NETCONF operation "get" without filtering
        Execution of "connect" method is a precondition.
        Validation is not performed in this method. Only raw output will be returned.
        :param session: string value example: "session1"
        :param with_defaults: enum [None, "report-all", "trim", "explicit", "report-all-tagged"].
        :return: output
        """
        return self.communication.get_without_filter(session, with_defaults)

    def edit_config(
        self,
        session: str,
        msg: dict,
        target="running",
        default_operation=None,
        test_option="set",
        error_option="continue-on-error",
        msg_format: str = "xml",
        validation_mode: str = "string",
        exclude_paths: Union[None, List[str]] = None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> str:
        """Method to execute NETCONF operation "edit_config".
        Execution of "connect" method is a precondition.
        :param session: string value example: "session1"
        :param msg: it is dict with request and expected response.
            Example of msg in format xml:
                               {"request": "<operational-info xmlns='urn:o-ran:operations:1.0'>"
                                           "<clock><timezone-utc-offset>10</timezone-utc-offset>"
                                           "</clock></operational-info>",
                                "expected_response": "<ok/>"
                                }
            Example of msg in format dictionary:
                               {"request": {
                                            "operational-info": {
                                                "@xmlns": "urn:o-ran:operations:1.0",
                                                "clock": {
                                                    "timezone-utc-offset": "10"
                                                }
                                              }
                                            },
                                "expected_response": "<ok/>"
                               }
        :param target: enum [running, candidate, startup] default=running
        :param default_operation: enum [none, merge, replace] default=merge
        :param test_option: enum [test-then-set, set, test-only] default=set
        :param error_option: enum [stop-on-error, continue-on-error, rollback-on-error]
               default=continue-on-error
        :param msg_format: enum ["xml", "dictionary"]
        :param validation_mode: enum ["string", "deepdiff", "skip_validation"]
            skip_validation - returns received response without validating it.
        :param exclude_paths: optional, used when validation_mode is deepdiff
        :param ignore_dictionary_item_added: ignores additional paths in response.
        :param ignore_iterable_item_added: ignores additional paths in response.
        :param kwargs:
                force_list - parameter that will contain tuple or key/value for given child which will be enforced to
                    be kept in list format.
                    Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                     when it is a single element
                log_ignored_items - additional parameter to log ignored items in deepdiff. By default, True.
                log_type_mismatch - additional parameter to log mismatched items in deepdiff.
                 By default, False.
                exclude_regex_paths: List of path regexes to exclude in deepdiff.
        :return: response as str
        """
        _timestamp, rsp = self.communication.edit_config(
            session=session,
            msg=msg,
            target=target,
            default_operation=default_operation,
            test_option=test_option,
            error_option=error_option,
            msg_format=msg_format,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )
        return rsp

    def edit_config_with_timestamp(
        self,
        session: str,
        msg: dict,
        target="running",
        default_operation=None,
        test_option="set",
        error_option="continue-on-error",
        msg_format: str = "xml",
        validation_mode: str = "string",
        exclude_paths: Union[None, List[str]] = None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> tuple[datetime, str]:
        """Edit NETCONF configuration and return the response along with its timestamp.

        All parameters are the same as in the edit_config method.
        Please note that the timestamp is more precise for SSH connections than for TLS due to implementation details.
        """
        return self.communication.edit_config(
            session=session,
            msg=msg,
            target=target,
            default_operation=default_operation,
            test_option=test_option,
            error_option=error_option,
            msg_format=msg_format,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )

    def create_subscription(self, session: str, noti_filter=None, stream_name=None, timeout=None):
        """Method to execute NETCONF operation "create_subscription" related with notifications.
        Execution of "connect" method is a precondition.
        :param session: string value example: "session1"
        :param noti_filter: by default it is subscribed to all kind of messages but we can
                            filter it via string
        :param stream_name: by default it is subscribed to all kind of streams but we can
                            filter it via string
        :param timeout: [seconds] by default it is infinity but we can also set it for few seconds
        :return: None or Exception
        """
        return self.communication.create_subscription(session, noti_filter, stream_name, timeout)

    def collect_notification(
        self,
        session: str,
        timeout: int,
        expected_notification: Union[str, dict],
        validation_mode: str = "deepdiff",
        exclude_paths: Union[None, List[str]] = None,
        reversed_order: bool = False,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> Union[Notification, str]:
        """Method to collect expected notification from the buffer.
        Execution of "connect" method is a precondition.
        :param session: string value example: "session1"
        :param timeout: [seconds]
        :param expected_notification:
        :param validation_mode: enum ["string", "deepdiff"]
        :param exclude_paths:
        :param reversed_order: flag which indicates whether notifications in buffer should be matched from:
            * reversed_order=True latest to earliest,
            * reversed_order=False earliest to latest.
        :param ignore_dictionary_item_added: ignores additional paths in response.
        :param ignore_iterable_item_added: ignores additional paths in response.
        :param kwargs:
                force_list - parameter that will contain tuple or key/value for given child which will be enforced to
                    be kept in list format.
                    Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                     when it is a single element
                log_ignored_items - additional parameter to log ignored items in deepdiff. By default, True.
                log_type_mismatch - additional parameter to log mismatched items in deepdiff.
                 By default, False.
                exclude_regex_paths: List of path regexes to exclude in deepdiff.
        :return: Received notification or Exception
        """
        return self.communication.collect_notification(
            session,
            timeout,
            expected_notification,
            validation_mode,
            exclude_paths,
            notification_expected=True,
            reversed_order=reversed_order,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )

    def check_lack_of_notifications(
        self,
        session: str,
        expected_notification: Union[str, dict],
        timeout: int,
        validation_mode: str = "string",
        exclude_paths: Union[None, List[str]] = None,
    ):
        """
        Method to verify whether given notification/s has not been received
        Execution of "connect" method is a precondition.
        :param session: string value example: "session1"
        :param timeout: [seconds]
        :param expected_notification:
        :param validation_mode: enum ["string", "deepdiff"]
        :param exclude_paths:
        :return: Received string with not found notification or ValidationException
        """
        return self.communication.collect_notification(
            session=session,
            timeout=timeout,
            expected_notification=expected_notification,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            notification_expected=False,
        )

    def clear_notifications_buffer_for_session(self, session):
        """Method to clear notification buffer for specific session.
        :param session: string value example: "session1"
        :return: None or Exception
        """
        self.communication.clear_notifications_buffer_for_session(session)

    def clear_notifications_buffer_for_all_sessions(self):
        """Method to clear notification buffer for all defined sessions.
        :return: None or Exception
        """
        self.communication.clear_notifications_buffer_for_all_sessions()

    def get_config(self, session: str, source: str):
        """Method to execute NETCONF operation "get_config"
        Execution of "connect" method is a precondition.
        :param session: string value example: "session1"
        :param source: enum: ["startup", "running", "candidate"]
        :return: config data for specific source
        """
        return self.communication.get_config(session, source)

    def get_server_capabilities(self, session: str):
        """Method to get server capabilities for NETCONF session.
        Execution of "connect" method is a precondition.
        :param session: string value example: "session1"
        :return: list of server capabilities
        """
        return self.communication.get_server_capabilities(session)

    def get_client_capabilities(self, session: str):
        """Method to get server capabilities for NETCONF session.
        Execution of "connect" method is a precondition.
        :param session: string value example: "session1"
        :return: list of client capabilities
        """
        return self.communication.get_client_capabilities(session)

    def monitoring_netconf_connectivity(
        self,
        session: str,
        *,
        supervision_notification_interval=60,
        guard_timer_overhead=10,
        loops=1,
        set_max_interval_in_last_loop=True,
        delta_time=1,
        skip_first_notification=False,
        validate_timestamps=False,
        validate_session_id: bool = False,
        odu_id: None | str = None,
    ):
        """This method describes "3.6 Monitoring NETCONF connectivity" from
        O-RAN Alliance Working Group 4 - Management Plane Specification
        :param session: string value example: "session1"
        :param supervision_notification_interval: timer for sending supervision-notification by RU
        :param guard_timer_overhead: timer for sending supervision-watchdog-reset by DU
        :param loops: number of loops to perform monitoring for
        :param set_max_interval_in_last_loop: boolean, if set to True max value for both timers will
                                              be set on last loop to ~36h hours
        :param delta_time: timestamp comparison accuracy in seconds
        :param skip_first_notification: boolean, if True makes the method start with
                                        watchdog_reset instead of notification check
        :param validate_timestamps: boolean, if True makes the method validate timestamp format
                                    in received messages and check differences between consecutive
                                    ones
        :param validate_session_id: boolean, if True makes the method validate session-id in received messages
        :param odu_id: optional O-DU identifier to be included in supervision-watchdog-reset RPC
        """
        self.procedures.monitoring_netconf_connectivity(
            session,
            supervision_notification_interval,
            guard_timer_overhead,
            loops,
            set_max_interval_in_last_loop,
            delta_time,
            skip_first_notification,
            validate_timestamps,
            validate_session_id,
            odu_id=odu_id,
        )

    def monitoring_netconf_connectivity_threaded(
        self,
        session: str,
        supervision_notification_interval: int,
        guard_timer_overhead: int,
        delta_time: int,
        threaded_logger: logging.Logger,
        odu_id: None | str = None,
    ) -> None:
        """Run a monitoring loop to continuously check for supervision notifications.

        This is a threaded implementation of ORAN WG4 MPlane Specification - 6.7 Monitoring NETCONF Connectivity.
        It is meant for continuous monitoring in the background, so it can handle small timer values.
        To stop a running monitoring thread, use the `stop_monitoring_thread` method.

        :param session: identifier of the session to monitor, e.g. "master_0". Should correspond to a valid session with
            a notification subscription established.
        :param supervision_notification_interval: the interval in seconds between notifications sent by the RU. Sent via
         the supervision-watchdog-reset RPC.
        :param guard_timer_overhead: additional time in seconds that the O-RU waits for a response from the O-DU after
            sending a supervision notification. Sent via the supervision-watchdog-reset RPC.
        :param delta_time: additional time in seconds to wait for the supervision notification to arrive. Not part of
         the specification, but added to account for network latency. Not sent via the supervision-watchdog-reset RPC.
        :param threaded_logger: logger object to use for logging in the monitoring thread. If None, messages will be
         logged to the default logger.
        :param odu_id: Optional ODU identifier to include in supervision-watchdog-reset RPC.
        """
        self.procedures.monitoring_netconf_connectivity_threaded(
            session, supervision_notification_interval, guard_timer_overhead, delta_time, threaded_logger, odu_id=odu_id
        )

    def stop_monitoring_thread(self, session: str) -> None:
        """Stop a running monitoring thread.

        :param session: identifier of the session to stop monitoring, e.g. "master_0".
        """
        self.procedures.stop_monitoring_thread(session)

    def stop_all_monitoring_threads(self) -> None:
        """Stop all running monitoring threads."""
        self.procedures.stop_all_monitoring_threads()

    def send_rpc(
        self,
        session: str,
        msg: dict,
        msg_format="xml",
        validation_mode: str = "deepdiff",
        exclude_paths: Union[None, List[str]] = None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> str:
        """send rpc
        :param session: string value example: "session1"
        :param msg: it is dict with request and expected response.
        :param msg_format: enum: ["xml", "dictionary"]
        :param validation_mode: enum ["string", "deepdiff", "skip_validation"]
        :param exclude_paths: optional, used when validation_mode is deepdiff
        :param ignore_dictionary_item_added: ignores additional paths in response.
        :param ignore_iterable_item_added: ignores additional paths in response.
        :param kwargs:
                force_list - Parameter that will contain tuple or key/value for given child which will be enforced to
                    be kept in list format.
                    Usage: force_list={'edit': True} or force_list=('edit') will force edit to be a list even
                     when it is a single element.
                log_ignored_items - Additional parameter to log ignored items in deepdiff. By default, True.
                log_type_mismatch - Additional parameter to log mismatched items in deepdiff.
                 By default, False.
                exclude_regex_paths: List of path regexes to exclude in deepdiff.
        :return: response as str
        """
        _timestamp, rsp = self.communication.send_rpc(
            session=session,
            msg=msg,
            msg_format=msg_format,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )
        return rsp

    def send_rpc_with_timestamp(
        self,
        session: str,
        msg: dict,
        msg_format="xml",
        validation_mode: str = "string",
        exclude_paths: Union[None, List[str]] = None,
        ignore_dictionary_item_added: bool = False,
        ignore_iterable_item_added: bool = False,
        **kwargs,
    ) -> tuple[datetime, str]:
        """Send RPC and return the response along with its timestamp.

        All parameters are the same as in the send_rpc method.
        Please note that the timestamp is more precise for SSH connections than for TLS due to implementation details.
        """
        return self.communication.send_rpc(
            session=session,
            msg=msg,
            msg_format=msg_format,
            validation_mode=validation_mode,
            exclude_paths=exclude_paths,
            ignore_dictionary_item_added=ignore_dictionary_item_added,
            ignore_iterable_item_added=ignore_iterable_item_added,
            **kwargs,
        )

    def collect_all_notifications(self, session: str) -> list:
        """
        Methods returns all notifications which were collected for session without validation.
        :param session:
        :return:
        """
        return self.communication.collect_all_notifications(session)

    def rpc_talker(self, rpc_directory, session):
        """
        Start RPC Talker
        :param: rpc_directory
        :param: session
        """

        talker = RpcTalker(
            connection=self.connection,
            communication=self.communication,
            protocol=self.router[session]["protocol"],
            logger=self.logger,
        )
        talker(rpc_directory, session)

    def get_session_id(self, *_, **kwargs) -> int:
        """
        Returns session id
        :return: int, session id
        """
        session = kwargs.get("session")
        return self.communication.get_session_id(session=session)

    def kill_session(self, session, session_id):
        """
        Kills specified session
        :param session:
        :param session_id:
        :return:
        """
        self.procedures.stop_monitoring_thread(session)
        return self.communication.kill_session(session=session, session_id=session_id)

    def validate_notification_event_time(self, notification: Notification, tolerance: int, tag: str = "event-time"):
        """
        Validate rpc-notif eventTime/event-time basing on time when notification was actually received with given
        tolerance.
        :param notification: Notification object to check,
        :param tag: indicates which time is to be validated: can take two values: eventTime or event-time,
        :param tolerance: tolerance for difference between generation and receive time.
         notification.
        """
        self.communication.validation.validate_notification_event_time(notification, tag=tag, tolerance=tolerance)
